"use client";
// ROC adapter for the installed Animate UI text primitive.
export { SplittingText } from "./motion-text";
import "./splitting-text.css";

"use client";
import { useEffect, useRef, type ComponentProps, type ReactNode } from "react";
import { AnimatePresence, animate, motion, useMotionValue } from "motion/react";
import { useRocReducedMotion, useRocTransition } from "./motion-config";
import { cn } from "./utils";
import "./motion-text.css";
import { GradientText as AnimateGradientText } from "@animate-ui/react/primitives/texts/gradient";
import { HighlightText as AnimateHighlightText } from "@animate-ui/react/primitives/texts/highlight";
import { MorphingText as AnimateMorphingText } from "@animate-ui/react/primitives/texts/morphing";
import { RollingText as AnimateRollingText } from "@animate-ui/react/primitives/texts/rolling";
import { ShimmeringText as AnimateShimmeringText } from "@animate-ui/react/primitives/texts/shimmering";
import { SlidingText as AnimateSlidingText } from "@animate-ui/react/primitives/texts/sliding";
import { SplittingText as AnimateSplittingText } from "@animate-ui/react/primitives/texts/splitting";
import { SwappingText as AnimateSwappingText } from "@animate-ui/react/primitives/texts/swapping";
import { TypingText as AnimateTypingText } from "@animate-ui/react/primitives/texts/typing";
import { RotatingText as AnimateRotatingText, RotatingTextContainer } from "@animate-ui/react/primitives/texts/rotating";

// Motion is supplied by the installed Animate UI package; ROC owns the host styling
// and the existing children/active API. No upstream source is vendored here.
export type TextMotionProps = Omit<ComponentProps<"span">, "children"> & { children: string; active?: boolean };
function TextFrame({ children, active = true, className, effect, render, retain = false, ...props }: TextMotionProps & {
  effect: string; retain?: boolean; render: (text: string) => ReactNode;
}) {
  const reduce = useRocReducedMotion();
  return <span {...props} className={cn("roc-ui roc-motion-text", className)} data-text-effect={effect} data-active={active && !reduce}>
    {(active || retain) && !reduce ? render(children) : children}
  </span>;
}
export function GradientText(props: TextMotionProps) {
  return <TextFrame {...props} effect="gradient" render={text => <AnimateGradientText text={text} gradient="linear-gradient(90deg, var(--roc-ink, #222), var(--roc-accent, #777), #aaa, var(--roc-accent, #777), var(--roc-ink, #222))" />} />;
}
export function HighlightText(props: TextMotionProps) {
  return <TextFrame {...props} effect="highlight" render={text => <AnimateHighlightText text={text} style={{ backgroundImage: "linear-gradient(var(--roc-marker, #e5e5e5), var(--roc-marker, #e5e5e5))" }} />} />;
}
export function MorphingText(props: TextMotionProps) {
  return <TextFrame {...props} effect="morphing" retain render={text => <AnimateMorphingText text={text} />} />;
}
export function RollingText(props: TextMotionProps) {
  return <TextFrame {...props} effect="rolling" render={text => <AnimateRollingText text={text} />} />;
}
export function RotatingText(props: TextMotionProps) {
  return <TextFrame {...props} effect="rotating" retain render={text => <RotatingTextContainer text={text} style={{ display: "inline-block", verticalAlign: "bottom" }}><AnimateRotatingText /></RotatingTextContainer>} />;
}
export function ShimmeringText(props: TextMotionProps) {
  return <TextFrame {...props} effect="shimmering" render={text => <AnimateShimmeringText text={text} color="var(--roc-ink, #222)" shimmeringColor="var(--roc-muted, #999)" />} />;
}
export function SlidingText(props: TextMotionProps) {
  return <TextFrame {...props} effect="sliding" render={text => <AnimateSlidingText text={text} trigger="hover" tabIndex={0} />} />;
}
export function SplittingText(props: TextMotionProps) {
  return <TextFrame {...props} effect="splitting" render={text => <AnimateSplittingText text={text} style={{ display: "inline" }} />} />;
}
export function SwappingText(props: TextMotionProps) {
  return <TextFrame {...props} effect="swapping" retain render={text => <AnimateSwappingText text={text} />} />;
}
export function TypingText({ speed = 45, ...props }: TextMotionProps & { speed?: number }) {
  return <TextFrame {...props} effect="typing" render={text => <span className="roc-typing-frame"><span aria-hidden="true" className="roc-typing-reserve">{text}</span><AnimateTypingText className="roc-typing-visible" text={text} duration={Math.max(16, speed)} /></span>} />;
}
export type NumberMotionProps = Omit<ComponentProps<"span">, "children"> & { value: number; decimals?: number; duration?: number };
export function CountingNumber({ value, decimals = 0, duration = 0.65, className, ...props }: NumberMotionProps) {
  const reduce = useRocReducedMotion(), number = useMotionValue(value), visible = useRef<HTMLSpanElement>(null);
  const places = Math.min(6, Math.max(0, decimals));
  const initialText = useRef(value.toFixed(places));
  useEffect(() => {
    const render = (n: number) => { if (visible.current) visible.current.textContent = n.toFixed(places); };
    render(number.get());
    const off = number.on("change", render);
    const control = animate(number, value, { duration: reduce ? 0 : Math.max(0, duration), ease: "easeOut" });
    return () => { off(); control.stop(); };
  }, [value, places, duration, number, reduce]);
  return <span {...props} className={cn("roc-ui roc-motion-number", className)}><span className="roc-ui-sr-only">{value.toFixed(places)}</span><span aria-hidden="true" ref={visible}>{initialText.current}</span></span>;
}
export function ScrollingNumber({ value, decimals = 0, className, ...props }: NumberMotionProps) {
  const transition = useRocTransition("control");
  const text = value.toFixed(Math.min(6, Math.max(0, decimals)));
  return <span {...props} className={cn("roc-ui roc-motion-number", className)}><span className="roc-ui-sr-only">{text}</span><span aria-hidden="true" className="roc-number-digits">{Array.from(text).map((digit, i) => /\d/.test(digit) ? <span key={text.length - i} className="roc-number-window"><motion.span initial={false} animate={{ y: `${Number(digit) * -10}%` }} transition={transition}>{Array.from({ length: 10 }, (_, n) => <span key={n}>{n}</span>)}</motion.span></span> : <span key={text.length - i}>{digit}</span>)}</span></span>;
}
export function SlidingNumber({ value, decimals = 0, className, ...props }: NumberMotionProps) {
  const reduce = useRocReducedMotion(), transition = useRocTransition();
  const text = value.toFixed(Math.min(6, Math.max(0, decimals)));
  return <span {...props} className={cn("roc-ui roc-motion-number roc-number-slide", className)}><span className="roc-ui-sr-only">{text}</span><span aria-hidden="true"><AnimatePresence initial={false} mode="popLayout"><motion.span key={text} initial={{ y: reduce ? 0 : "100%", opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: reduce ? 0 : "-100%", opacity: 0 }} transition={transition}>{text}</motion.span></AnimatePresence></span></span>;
}

"use client";
import { type ReactNode } from "react";
import { AnimateUIProvider } from "@animate-ui/react/provider";
import { motionTokens, useShouldReduceMotion, useTempoTransition, type CheckAnimation, type ReducedMotion } from "@animate-ui/react/utils/motion";
import { MotionConfig, type Transition } from "motion/react";

/** ROC's public defaults feed the same provider used by every Animate UI primitive. */
export function RocMotionProvider({ children, pace, reducedMotion, checkAnimation }: {
  children: ReactNode; pace?: number; reducedMotion?: ReducedMotion; checkAnimation?: CheckAnimation;
}) {
  return <AnimateUIProvider tempo={pace === undefined ? undefined : Math.max(0.1, pace)} reducedMotion={reducedMotion} checkAnimation={checkAnimation}>
    <MotionConfig reducedMotion={reducedMotion}>{children}</MotionConfig>
  </AnimateUIProvider>;
}
/** For ROC-only compositions; timings and tempo come from Animate UI. */
export function useRocTransition(kind: "control" | "surface" = "surface"): Transition {
  const transition = useTempoTransition(kind === "control" ? motionTokens.spring.thumb : motionTokens.spring.dialog);
  const reduce = useRocReducedMotion();
  return reduce ? { duration: 0 } : transition;
}
export const useRocReducedMotion = useShouldReduceMotion;

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-motion-text { position: relative; font-size: inherit; line-height: 1.4; }
.roc-motion-text > [data-slot="splitting-text"] { display: inline; }
.roc-typing-frame { display: inline-grid; }
.roc-typing-reserve, .roc-typing-visible { grid-area: 1 / 1; }
.roc-typing-reserve { visibility: hidden; }
.roc-motion-number { font-size: inherit; font-variant-numeric: tabular-nums; display: inline-block; line-height: 1.2; }
.roc-number-digits { display: inline-flex; }
.roc-number-window { height: 1.2em; width: 1ch; overflow: hidden; display: inline-block; }
.roc-number-window > span { display: flex; flex-direction: column; }
.roc-number-window > span > span { height: 1.2em; }
.roc-number-slide { overflow: hidden; vertical-align: bottom; }
.roc-number-slide > span[aria-hidden] { display: inline-block; position: relative; }
.roc-number-slide > span[aria-hidden] > span { display: inline-block; }

@import "./tokens.css";
@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-family: var(--roc-font-body, inherit);
  font-size: var(--roc-text-body, 13px);
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible,
.roc-shadcn:focus-visible {
  outline: none;
  /* Draw the focus border inward, without changing the control's dimensions.
     Keep it visible when component hover or utility styles set box-shadow. */
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
.roc-shadcn:focus {
  /* Imported utilities must not add an outer focus ring or its offset. */
  --roc-sh-tw-ring-shadow: 0 0 #0000 !important;
  --roc-sh-tw-ring-offset-shadow: 0 0 #0000 !important;
}
@media (forced-colors: active) {
  .roc-ui:focus-visible,
  .roc-shadcn:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

/* Shared design tokens for ROC practice cases. Hosts may override any --roc-* token. */
:where(:root) {
  --roc-ink: #252525;
  --roc-muted: #737373;
  --roc-paper: #ffffff;
  --roc-line: #e5e5e5;
  --roc-accent: #1a1a1a;
  --roc-accent-foreground: #ffffff;
  --roc-marker: #efefef;
  --roc-focus: #737373;
  --roc-font-body: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --roc-font-heading: var(--roc-font-body);
  --roc-font-control: var(--roc-font-body);
  --roc-font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --roc-text-body: 13px;
  --roc-weight-control: 500;
  --roc-radius: 12px;
  --roc-space-1: 4px;
  --roc-space-2: 8px;
  --roc-space-3: 12px;
  --roc-space-4: 16px;
  --roc-space-6: 24px;
  --roc-space-8: 32px;
  --roc-control-height: 36px;
}

/* Animate UI owns presence. CSS keyframes must not compete with Motion's
   transforms/opacity or keep an exiting portal alive a second time. */
[data-roc-motion="animate-ui"][data-slot] {
  animation: none !important;
}
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}
